(function(){
 'use strict';
 const NS='http://www.w3.org/2000/svg',DURATION=180;
 const labels={
  ar:{title:'EcoTwin — أثر القرار عبر الزمن',intro:'أثر القرار على الانتظار والحافلات والوقود عند الزمن نفسه. النسبة فوق 1 تعني نتيجة أسوأ من التوقيت الثابت؛ اختر المؤشر لقراءة الفرق.',tag:'محاكاة توضيحية · جميع الاتجاهات',radial:'عرض دائري',bars:'عرض خطي',play:'تشغيل',pause:'إيقاف مؤقت',replay:'إعادة التشغيل',reset:'من البداية',time:'زمن المحاكاة',speed:'سرعة العرض',lower:'أقل من خط الأساس',reference:'خط الأساس = 1×',higher:'أعلى من خط الأساس',ratio:'نسبة CO₂ إلى التوقيت الثابت',dataHint:'يُحدَّث النموذجان بنفس الطلب والمدة. القيم الأقل أفضل؛ وقد يتفوق التوقيت الثابت في بعض اللحظات.',keys:['الانتظار','الطابور','التوقف','الوقود','CO₂','تأخر الحافلات'],units:['ث','مركبة','مركبة·ث','لتر','كغ','ث'],current:'المعروض',fixed:'الثابت',noData:'لا بيانات كافية للمقارنة بعد',emptyBase:'خط الأساس صفري؛ النسبة غير معرّفة',assumptions:'الافتراضات وحدود القراءة',method:'الرسم مستوحى من الفيديو، وليس قياسًا للحدود الكوكبية. الانتظار هو مجموع تأخير المركبات ÷ عدد المركبات الوافدة، ويشمل الاتجاهات الأربعة والطابور خارج الشاشة. التوقف هو مجموع ثواني المركبات المتوقفة. الوقود = (ثواني التوقف × 0.8 + ثواني الحركة × 4) ÷ 3600 لتر؛ معدلا الاستهلاك افتراضان توضيحيان غير معايرين. نفترض أسطولًا مكافئًا للبنزين لجميع الرموز، بما فيها الحافلات، ولا نمثل محركات الديزل الفعلية. CO₂ مشتق من الوقود؛ لذا ليس مؤشرًا مستقلًا عنه. لا نحسب NOx أو PM2.5 أو EcoScore.',source:'معامل EPA: ‏8.887 كغ CO₂ لكل غالون أمريكي ≈ 2.348 كغ/لتر.',clip:'أسلوب بصري مستوحى من الفيديو المرفق',signalGreen:'أخضر',signalAmber:'أصفر · منع دخول جديد',signalClear:'أحمر للجميع · إخلاء التقاطع',northSouth:'شمال–جنوب',eastWest:'شرق–غرب',safe:'فصل المسارات + مسافة أمان',vehicles:'المركبات العابرة',bus:'حافلة',car:'مركبة',ambulance:'إسعاف',legend:'الحلقات مرجع نسبي؛ ألوان الزيادة ليست حدودًا علمية للخطر.',axis:'تفصيل المؤشر',timelineHint:'اسحب الزمن لإعادة بناء الحركة والنتائج عند اللحظة نفسها.',motionPause:'إيقاف المحاكاة Ⅱ',motionResume:'تشغيل المحاكاة ▷',queueApproach:'الاتجاهات الأربعة',computed:'من نموذج المتصفح',cloud:'السحابة متصلة افتراضيًا',offline:'السحابة مفصولة · القرار محلي',initial:'اضغط تشغيل لبدء حركة المركبات',live:'زمن نموذجي، وليس قياسًا ميدانيًا',guard:'فحص هندسي للتداخل',allClear:'لا تداخل في الحالة الحالية',guardFail:'توقف آمن: اكتُشف تداخل',safetyNote:'التحقق يخص نموذج المتصفح فقط.'},
  en:{title:'EcoTwin — the impact over time',intro:'Compare waiting, bus delay and fuel at the same experiment time. A ratio above 1 means a worse result than fixed timing.',tag:'ILLUSTRATIVE · ALL APPROACHES',radial:'Radial view',bars:'Bar view',play:'Play',pause:'Pause',replay:'Replay',reset:'Restart',time:'Simulation time',speed:'Playback speed',lower:'Below baseline',reference:'Baseline = 1×',higher:'Above baseline',ratio:'CO₂ relative to fixed timing',dataHint:'Both models share the same demand and duration. Lower is better; fixed timing may perform better at some points.',keys:['Waiting','Queue','Idling','Fuel','CO₂','Bus delay'],units:['s','vehicles','vehicle·s','L','kg','s'],current:'Displayed',fixed:'Fixed',noData:'Not enough data for a comparison yet',emptyBase:'Zero baseline; ratio is undefined',assumptions:'Assumptions & reading guide',method:'This chart borrows the video’s visual approach; it does not measure planetary boundaries. Waiting is total vehicle delay divided by arrivals, across all four approaches including upstream queues outside the view. Idling sums stationary vehicle-seconds. Fuel = (idle seconds × 0.8 + moving seconds × 4) ÷ 3600 litres; both consumption rates are uncalibrated illustrative assumptions. Every symbol, including buses, uses a gasoline-equivalent fleet assumption, not a diesel-engine model. CO₂ is derived from fuel and is not independent of it. NOx, PM2.5 and EcoScore are not calculated.',source:'EPA factor: 8.887 kg CO₂ per US gallon ≈ 2.348 kg/L.',clip:'Visual approach inspired by your supplied clip',signalGreen:'Green',signalAmber:'Amber · no new entries',signalClear:'All red · clearing intersection',northSouth:'North–south',eastWest:'East–west',safe:'Separated lanes + safe following gaps',vehicles:'Vehicles through',bus:'Bus',car:'Vehicle',ambulance:'Ambulance',legend:'Rings are relative references. Increase colors are not scientific risk thresholds.',axis:'Indicator detail',timelineHint:'Scrub time to rebuild traffic and results at the same instant.',motionPause:'Pause simulation Ⅱ',motionResume:'Run simulation ▷',queueApproach:'All four approaches',computed:'Browser model output',cloud:'Simulated cloud connection',offline:'Cloud offline · local decisions',initial:'Press play to start traffic',live:'Model time, not a field measurement',guard:'Geometric overlap check',allClear:'No overlap in the current state',guardFail:'Safe stop: overlap detected',safetyNote:'Verification applies to this browser model only.'}
 };
 const keys=['waiting','queue','idle','fuel','co2','busDelay'];
 let engines={},last=0,accumulator=0,paintElapsed=0,ecoLast=0,lang='',nodes=new Map(),signalNodes=[],speed=3,chartView='radial',selected=4,fail=false,seekGeneration=0,seeking=false;
 const L=()=>labels[state.lang];
 const svgEl=(tag,attrs={})=>{const n=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs))n.setAttribute(k,v);return n;};
 const fmt=(v,d=1)=>Number.isFinite(v)?v.toFixed(d):'—';
 const clock=v=>`${String(Math.floor((v+1e-6)/60)).padStart(2,'0')}:${String(Math.floor((v+1e-6)%60)).padStart(2,'0')}`;
 function init(){engines={baseline:new TrafficEngine({mode:'baseline',scenario:state.scenario,demand:state.demand}),optimized:new TrafficEngine({mode:'optimized',scenario:state.scenario,demand:state.demand})};accumulator=0;fail=false;}
 function engine(){return engines[state.mode];}
 function time(){return engines.baseline.time;}
 function mount(){
  const map=$('#map');
  map.querySelectorAll('.car-horizontal,.car-vertical,.queue-car,.ambulance-car,.map-flow').forEach(n=>n.remove());
  map.querySelectorAll('.signal-dot').forEach(n=>n.closest('g')?.remove());
  map.querySelectorAll('#traffic-cars,#traffic-signals,#traffic-routes').forEach(n=>n.remove());nodes=new Map();signalNodes=[];
  const routes=svgEl('g',{id:'traffic-routes'});TrafficEngine.lanes.forEach((lane,i)=>{const route=TrafficEngine.routes[i][lane.movement],d=route.points.filter((p,j)=>j%4===0||j===route.points.length-1).map(p=>`${p.x},${p.y}`).join(' ');routes.append(svgEl('polyline',{points:d,'data-route-lane':i,fill:'none',stroke:'#9acaab','stroke-width':1,'stroke-dasharray':'5 9',opacity:.1}));});map.append(routes);
  const signals=svgEl('g',{id:'traffic-signals'});
  TrafficEngine.lanes.forEach((lane,i)=>{const [x,y]=IntersectionMap.signalPosition(i),g=svgEl('g',{transform:`translate(${x} ${y})`,'data-signal-lane':i});g.append(svgEl('rect',{x:-9,y:-25,width:18,height:42,rx:4,fill:'#09191d',stroke:'#8d9d8b','stroke-width':.7}));const cs=['red','amber','green'].map((c,j)=>{const n=svgEl('circle',{cx:0,cy:j*12-17,r:4,fill:'#354241'});g.append(n);return n});const label=svgEl('text',{x:0,y:31,'text-anchor':'middle',fill:'#e0e7d2','font-size':15});label.textContent=lane.movement==='left'?'↰':lane.movement==='right'?'↱':'↑';g.append(label);const title=svgEl('title');title.textContent=lane.id;g.append(title);signals.append(g);signalNodes.push({lane:i,cs,g});});map.append(signals,svgEl('g',{id:'traffic-cars'}));
  let status=$('#signal-status');if(!status){status=document.createElement('div');status.id='signal-status';status.className='signal-status';$('.map-wrap').append(status);}
  let overlay=$('#map-playback-state');if(!overlay){overlay=document.createElement('div');overlay.id='map-playback-state';overlay.className='map-playback-state';$('.map-wrap').append(overlay);}
  let phases=$('#junction-phases');if(!phases){phases=document.createElement('div');phases.id='junction-phases';$('.map-footer').after(phases);}
  paint();
 }
 function buildEco(){
  let section=$('#ecotwin');if(!section){section=document.createElement('section');section.id='ecotwin';section.className='eco-section';$('.insights-row').before(section);}
  const l=L();section.innerHTML=`<div class="eco-heading"><div><span class="eyebrow mono">ECOTWIN / 02</span><h2>${l.title}</h2><p>${l.intro}</p></div><span class="mini-tag">${l.tag}</span></div><div class="eco-workspace"><div class="eco-visual"><div class="eco-visual-head"><span class="mono">IMPACT OBSERVATORY</span><div class="eco-switch" role="group" aria-label="${l.radial} / ${l.bars}"><button id="eco-radial">${l.radial}</button><button id="eco-bars">${l.bars}</button></div></div><div class="eco-gauge-label"><span>${l.ratio}</span><b id="eco-ratio" class="mono">—</b></div><div class="eco-gauge" dir="ltr"><i class="gauge-reference"></i><i id="eco-marker"></i></div><div class="eco-gauge-captions"><span>${l.lower}</span><span>${l.reference}</span><span>${l.higher}</span></div><svg id="eco-chart" viewBox="0 0 500 440" role="img" aria-label="${l.title}"></svg><div id="eco-bar-chart" hidden></div><p class="eco-legend">${l.legend}</p></div><div class="eco-readout"><div class="eco-readout-head"><h3>${l.axis}</h3><span class="mono" id="eco-scene"></span></div><div class="eco-readout-columns"><span></span><span>${l.current}</span><span>${l.fixed}</span></div><div id="eco-indicators">${keys.map((k,i)=>`<button class="eco-indicator" data-eco-axis="${i}" aria-pressed="${i===selected}"><span><i class="eco-key">0${i+1}</i>${l.keys[i]}</span><strong id="eco-value-${i}">—</strong><span id="eco-base-${i}">—</span></button>`).join('')}</div><div id="eco-selected" class="eco-selected" role="status"></div><p class="eco-data-hint">${l.dataHint}</p><div class="eco-safety"><span class="status-dot"></span><span id="safety-report">${l.allClear}</span><small>${l.safetyNote}</small></div><div class="eco-through"><span>${l.vehicles}</span><b id="eco-through-value" class="mono">0</b></div></div></div><div class="eco-timeline"><div class="eco-playback"><button id="eco-play" class="eco-play"></button><button id="eco-reset" class="eco-reset" aria-label="${l.reset}">↺</button><label for="eco-time">${l.time}</label><output id="eco-time-value" class="mono">00:00 / 03:00</output><label class="eco-speed-label" for="eco-speed">${l.speed}</label><select id="eco-speed"><option value="1">1×</option><option value="3">3×</option><option value="6">6×</option></select></div><input id="eco-time" type="range" min="0" max="180" step="1" value="0" aria-label="${l.time}"><div class="eco-time-marks mono" dir="ltr"><span>00:00</span><span>01:00</span><span>02:00</span><span>03:00</span></div><p>${l.timelineHint}</p></div><details class="eco-method"><summary>${l.assumptions}<span>+</span></summary><p>${l.method}</p><a href="https://www.epa.gov/greenvehicles/greenhouse-gas-emissions-typical-passenger-vehicle" target="_blank" rel="noopener noreferrer">${l.source} ↗</a><p class="quiet">${l.clip}</p></details>`;
  $('#eco-play').onclick=toggleRun;$('#eco-reset').onclick=resetRun;$('#eco-time').oninput=e=>seek(Number(e.target.value));$('#eco-speed').value=String(speed);$('#eco-speed').onchange=e=>{speed=Number(e.target.value)};
  $('#eco-radial').onclick=()=>{chartView='radial';paintEco(true)};$('#eco-bars').onclick=()=>{chartView='bars';paintEco(true)};
  $$('[data-eco-axis]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.ecoAxis);paintEco(true)});
  $('#eco-selected').removeAttribute('role');
  lang=state.lang;paintEco(true);
 }
 function ratio(a,b){return b>0.00001?a/b:a<=.00001?1:null;}
 function sector(index,r){const a=(index*60-90+3)*Math.PI/180,b=((index+1)*60-90-3)*Math.PI/180;return `M250 218 L${250+r*Math.cos(a)} ${218+r*Math.sin(a)} A${r} ${r} 0 0 1 ${250+r*Math.cos(b)} ${218+r*Math.sin(b)}Z`;}
 function paintEco(force=false){
  if(state.running&&!force&&performance.now()-ecoLast<200)return;ecoLast=performance.now();
  if(!$('#eco-chart'))return;const l=L(),a=engine().snapshot(),b=engines.baseline.snapshot();
  const ratios=keys.map(k=>ratio(a[k],b[k]));const active=ratios[selected];
  const color=r=>r===null?'#738580':r<=1?'#92c79d':r<=1.25?'#d4bd76':r<=1.5?'#d38c61':'#c56b7e';
  const r=ratios[4];$('#eco-ratio').textContent=time()<1?'—':r===null?'—':fmt(r,2)+'×';$('#eco-marker').style.left=Math.min(98,Math.max(2,(r??2)/2*100))+'%';
  $('#eco-chart').style.display=chartView==='radial'?'block':'none';$('#eco-bar-chart').hidden=chartView!=='bars';
  for(const [id,view]of [['eco-radial','radial'],['eco-bars','bars']]){$('#'+id).classList.toggle('active',chartView===view);$('#'+id).setAttribute('aria-pressed',String(chartView===view));}
  let chart=`<defs><radialGradient id="eco-fill" gradientUnits="userSpaceOnUse" cx="250" cy="218" r="180"><stop offset="0" stop-color="#78b885"/><stop offset="49%" stop-color="#9ec575"/><stop offset="65%" stop-color="#dfc06e"/><stop offset="82%" stop-color="#c58269"/><stop offset="100%" stop-color="#a45f85"/></radialGradient></defs><circle cx="250" cy="218" r="180" fill="#172b2d"/>`;
  ratios.forEach((v,i)=>{const rad=Math.max(8,Math.min(180,(v??2)*90));chart+=`<path d="${sector(i,rad)}" fill="url(#eco-fill)" opacity="${i===selected?'.95':'.72'}" stroke="${i===selected?'#f3eed8':'none'}" stroke-width="1.3"/>`;});
  [45,90,135,180].forEach((rad,i)=>{chart+=`<circle cx="250" cy="218" r="${rad}" fill="none" stroke="${i===1?'#d4e7c2':'#55706a'}" stroke-width="${i===1?1.5:.6}" stroke-dasharray="${i===1?'4 4':'2 6'}"/><text x="254" y="${218-rad+12}" fill="#b2c5b5" font-size="9" font-family="Space Grotesk">${(i+1)*.5}×</text>`;});
  l.keys.forEach((name,i)=>{const a=(i*60-60)*Math.PI/180,x=250+205*Math.cos(a),y=218+205*Math.sin(a);chart+=`<text x="${x}" y="${y}" text-anchor="middle" dominant-baseline="middle" fill="#c9d7ce" font-size="${state.lang==='ar'?12:11}" font-family="${state.lang==='ar'?'IBM Plex Sans Arabic':'Space Grotesk'}">${name}</text>`;});
  chart+=`<circle cx="250" cy="218" r="14" fill="#122023" stroke="#789b85"/><path d="M243 218h14m-7-7v14" stroke="#c3dfb9"/>`;
  $('#eco-chart').innerHTML=chart;
  $('#eco-bar-chart').innerHTML=ratios.map((v,i)=>`<div class="eco-linear-row"><span>${l.keys[i]}</span><div><i style="width:${Math.min(100,(v??2)*50)}%;background:${color(v)}"></i><b></b></div><strong class="mono">${v===null?'—':fmt(v,2)+'×'}</strong></div>`).join('');
  keys.forEach((k,i)=>{$('#eco-value-'+i).textContent=fmt(a[k],i===1?0:k==='fuel'||k==='co2'?3:1)+' '+l.units[i];$('#eco-base-'+i).textContent=fmt(b[k],i===1?0:k==='fuel'||k==='co2'?3:1)+' '+l.units[i];});
  $$('[data-eco-axis]').forEach((btn,i)=>{btn.classList.toggle('selected',i===selected);btn.setAttribute('aria-pressed',String(i===selected))});
  const relation=active!==null&&Math.abs(active-1)<.005?(state.lang==='ar'?'قريب من خط الأساس':'Close to baseline'):active<=1?l.lower:l.higher;
  $('#eco-selected').textContent=time()<1?l.noData:active===null?l.emptyBase:`${l.keys[selected]}: ${fmt(a[keys[selected]]-b[keys[selected]],selected===1?0:selected===3||selected===4?3:1)} ${l.units[selected]} · ${fmt(active,2)}× — ${relation}`;
  $('#eco-scene').textContent=t(state.scenario);$('#eco-through-value').textContent=`${a.crossed} / ${b.crossed}`;
  $('.eco-readout-columns span:nth-child(2)').textContent=t(state.mode==='optimized'?'optimized':'baseline');
  $('#eco-play').textContent=state.running?'Ⅱ '+l.pause:state.complete?'↺ '+l.replay:'▷ '+l.play;
  $('#eco-time-value').textContent=clock(time())+' / 03:00';$('#eco-time').value=Math.floor(time()+1e-6);
  $('#safety-report').textContent=fail?l.guardFail:l.allClear;
 }
 function paintComparison(b,opt){
  const say=(ar,en)=>state.lang==='ar'?ar:en;
  const ready=time()>=1,improvement=b.waiting-opt.waiting;
  const percent=b.waiting>.001?Math.abs(improvement/b.waiting*100):null;
  $('#comparison-title').textContent=say('ما الفرق الفعلي في هذه التجربة؟','What actually changed in this experiment?');
  $('#comparison-context').textContent=`${t(state.scenario)} · ${state.demand}% · ${clock(time())}`;
  $('#comparison-metric').textContent=say('متوسط الانتظار المتراكم لكل مركبة وافدة · الأقل أفضل','Accumulated average waiting per arriving vehicle · lower is better');
  $('#comparison-summary').innerHTML=!ready?`<p>${say('ابدأ التجربة أو حرّك شريط الزمن لقياس الفرق.','Start the experiment or scrub the timeline to measure the difference.')}</p>`:`<p><strong>${Math.abs(improvement)<.05?say('المتوسط متقارب في هذه اللحظة.','The averages are close at this instant.'):say(improvement>0?'انخفض المتوسط بمقدار ':'ارتفع المتوسط بمقدار ',improvement>0?'Average waiting decreased by ':'Average waiting increased by ')+`<span class="mono">${fmt(Math.abs(improvement),2)} s</span>`+(percent===null?'':` <span class="mono">(${fmt(percent)}%)</span>`)}</strong> ${say('هذا فرق المتوسط، وليس توفيرًا متساويًا لكل مركبة.','This is a difference in averages, not an equal saving for each vehicle.')}</p><p>${improvement>0&&percent!==null&&percent<10?say('التحسن في متوسط المركبات محدود هنا؛ اقرأ أثر الحافلات والإسعاف بشكل مستقل أدناه.','The improvement in average vehicle waiting is modest here; read bus and ambulance outcomes separately below.'):say('اقرأ كل مؤشر على حدة؛ انخفاض المتوسط لا يضمن تحسن جميع المركبات أو الحافلات.','Read each outcome separately; a lower average does not guarantee that every vehicle or bus improves.')}</p>`;
  const seconds=say('ث','s'),vehicleSeconds=say('مركبة·ث','vehicle·s');
  const rows=[
   {name:say('مجموع انتظار جميع المركبات','Total waiting across all vehicles'),base:engines.baseline.waitSeconds,adaptive:engines.optimized.waitSeconds,unit:vehicleSeconds,note:say('يشمل الحافلات والطوابير خارج الشاشة؛ ليس مؤشرًا مستقلًا عن المتوسط.','Includes buses and upstream queues; not independent of the average.')},
   {name:say('متوسط تأخر الحافلات','Average bus delay'),base:b.busDelay,adaptive:opt.busDelay,unit:seconds,relative:true,available:engines.baseline.busArrived>0,note:say('مجموع انتظار الحافلات ÷ عدد الحافلات الوافدة.','Total bus waiting divided by bus arrivals.')},
   {name:say('زمن عبور الإسعاف','Ambulance crossing time'),base:b.emergency,adaptive:opt.emergency,unit:seconds,relative:true,available:b.emergency!==null&&opt.emergency!==null,note:state.scenario==='ambulance'?say('من دخول طلب الإسعاف إلى اكتمال عبوره؛ ينتظر القياس اكتمال العبور في التجربتين.','From ambulance request arrival until crossing completes; both runs must finish crossing.'):say('لا يوجد طلب إسعاف في هذا المشهد.','There is no ambulance request in this scenario.')},
   {name:say('المركبات التي أكملت العبور','Vehicles that completed crossing'),base:b.crossed,adaptive:opt.crossed,unit:say('مركبة','vehicles'),higher:true,digits:0,note:say('حتى اللحظة المعروضة، وليس عدد المركبات الوافدة.','Through the displayed instant, not the number of arrivals.')}
  ];
  $('#comparison-outcomes').innerHTML=`<div class="comparison-table-head"><span>${say('المؤشر','Outcome')}</span><span>${say('الثابت ← التكيفي','Fixed → adaptive')}</span><span>${say('الفرق الفعلي','Actual difference')}</span></div>`+rows.map(row=>{
   const available=ready&&row.available!==false,difference=available?row.adaptive-row.base:0,neutral=Math.abs(difference)<.05,better=row.higher?difference>0:difference<0;
   const change=!available?'—':neutral?say('متقارب','Similar'):`${fmt(Math.abs(difference),row.digits??2)} ${row.unit} `+(row.higher?say(difference>0?'أكثر':'أقل',difference>0?'more':'fewer'):say(difference<0?'أقل':'أكثر',difference<0?'less':'more'));
   return `<div class="comparison-outcome"><div><h4>${row.name}</h4><p>${row.note}</p></div><span class="mono comparison-pair">${available?fmt(row.base,row.digits??2)+' → '+fmt(row.adaptive,row.digits??2):'—'} <small>${row.unit}</small></span><strong class="comparison-delta ${!available||neutral?'neutral':better?'gain':'loss'}">${change}${available&&!neutral&&row.relative&&row.base>0?`<small class="mono">${fmt(Math.abs(difference)/row.base*100)}%</small>`:''}</strong></div>`;
  }).join('');
  $('#comparison-method').textContent=say(`المقارنة دائمًا: التكيفي مقابل الثابت، حتى لو عرضت حركة التوقيت الثابت. نفس الطلب ونفس الزمن؛ ${b.arrived} مركبة وافدة لكل تجربة، منها ${engines.baseline.busArrived} حافلة. المتوسط = مجموع ثواني الانتظار ÷ الوافدين، ويشمل من لم يكمل العبور. تُحسب الفروق والنسب قبل تقريب الأرقام للعرض. هذه نتيجة النموذج الحالي، لا وعد بتحسن ميداني أو توفير يومي.`, `Always adaptive versus fixed, even when fixed traffic is displayed. Identical demand and elapsed time; ${b.arrived} arrivals per run, including ${engines.baseline.busArrived} buses. Average = total waiting seconds / arrivals, including unfinished crossings. Differences and percentages are calculated before display rounding. This is a current model result, not a field benefit or daily saving projection.`);
 }
 function paint(){
  if(!engines.baseline)return;const e=engine(),l=L(),layer=$('#traffic-cars');
  if(layer){const live=new Set();for(const v of e.vehicles){live.add(v.id);let g=nodes.get(v.id);if(!g){g=svgEl('g',{'data-vehicle':v.id});const isBus=v.type==='bus',isAmb=v.type==='ambulance';g.append(svgEl('rect',{x:-v.length/2,y:-4.5,width:v.length,height:9,rx:2,fill:isBus?'#b7d18b':isAmb?'#f1e8dc':'#a4c6c1',stroke:'#0e1e24','stroke-width':.7}));g.append(svgEl('rect',{x:v.length/2-6,y:-3.5,width:4,height:7,rx:.6,fill:'#334d53'}));if(isAmb){g.append(svgEl('rect',{x:-20,y:-11,width:40,height:22,rx:6,fill:'none',stroke:'#f2ac77','stroke-width':2}));g.append(svgEl('path',{d:'M-6 0h7m-3.5-3.5v7',stroke:'#ce765d','stroke-width':2}));}if(isBus)g.append(svgEl('path',{d:'M-10 -2h12m-12 4h12',stroke:'#536e61','stroke-width':1.7}));const title=svgEl('title');title.textContent=`${l[v.type]} ${v.id} · ${v.movement}`;g.append(title);layer.append(g);nodes.set(v.id,g)}const {x,y,angle}=e.pose(v);g.setAttribute('transform',`translate(${x.toFixed(2)} ${y.toFixed(2)}) rotate(${angle.toFixed(2)})`);g.dataset.x=x.toFixed(2);g.dataset.y=y.toFixed(2);g.dataset.speed=v.speed.toFixed(2);g.dataset.lane=TrafficEngine.lanes[v.lane].id;g.dataset.movement=v.movement;}
    for(const[id,g]of nodes)if(!live.has(id)){g.remove();nodes.delete(id)}
    signalNodes.forEach(({lane,cs,g})=>{const color=e.signal(lane),idx=color==='green'?2:color==='amber'?1:0;g.dataset.signal=color;g.dataset.displaySignal=state.running?color:'off';g.setAttribute('opacity',state.running?'1':'.65');cs.forEach((c,i)=>c.setAttribute('fill',state.running&&i===idx?['#e58c7e','#efd080','#afe094'][i]:'#354241'));});
    $$('[data-route-lane]').forEach(path=>path.setAttribute('opacity',e.isGreen(Number(path.dataset.routeLane))?'.33':'.04'));
  }
  if($('#signal-status')){$('#signal-status').textContent=(!state.running?(state.lang==='ar'?'حالة محفوظة · ':'Saved state · '):'')+(e.phase==='clearance'?l.signalClear:`${window.junctionStageName(e.stage,state.lang)} · ${e.phase==='green'?l.signalGreen:l.signalAmber}`);$('#signal-status').dataset.phase=e.phase;}
  const a=e.snapshot(),b=engines.baseline.snapshot(),opt=engines.optimized.snapshot();
  const delta=(n,base)=>base>.001?`${n>base?'+':n<base?'−':''}${Math.abs((1-n/base)*100).toFixed(0)}%`:'—';
  $('#wait-value').textContent=fmt(a.waiting);$('#queue-value').textContent=a.queue;$('#emergency-value').textContent=a.emergency===null?'—':fmt(a.emergency);
  $('#wait-change').textContent=delta(a.waiting,b.waiting);$('#wait-change').classList.toggle('worse',a.waiting>b.waiting+.01);$('#emergency-change').textContent=a.emergency===null||b.emergency===null?'—':delta(a.emergency,b.emergency);$('#emergency-change').classList.toggle('worse',a.emergency!==null&&b.emergency!==null&&a.emergency>b.emergency);
  $('#wait-base').textContent=fmt(b.waiting)+' s';$('#baseline-label').textContent=fmt(b.waiting,2)+'s';$('#optimized-label').textContent=fmt(opt.waiting,2)+'s';const max=Math.max(1,b.waiting,opt.waiting);$('#baseline-bar').style.width=b.waiting/max*90+'%';$('#optimized-bar').style.width=opt.waiting/max*90+'%';
  paintComparison(b,opt);
  $('[data-i18n="northApproach"]').textContent=l.queueApproach;$$('[data-i18n="illustrative"]').forEach(n=>n.textContent=l.computed);$('#cloud-status').textContent=state.scenario==='offline'&&time()>0?l.offline:l.cloud;
  $('#motion').textContent=state.running?l.motionPause:l.motionResume;$('#motion').setAttribute('aria-pressed',String(!state.running));
  $('#demand-value').textContent=state.demand+'%';$('#map').dataset.simTime=time().toFixed(2);$('#map').dataset.overlaps=String(fail?1:0);
  const overlay=$('#map-playback-state');if(overlay){overlay.hidden=state.running;overlay.textContent=seeking?(state.lang==='ar'?'جارٍ إعادة بناء التجربة…':'Rebuilding experiment…'):state.complete?(state.lang==='ar'?'انتهت التجربة · مشهد محفوظ':'Experiment ended · saved state'):time()<.01?(state.lang==='ar'?'جاهز · ابدأ التجربة لتحريك المركبات':'Ready · start the experiment to move traffic'):(state.lang==='ar'?'متوقفة مؤقتًا · الإشارات تعرض آخر حالة':'Paused · signals show the last state');}
  if($('#junction-phases')){$('#junction-phases').dataset.phase=state.running?e.phase:'paused';$('#junction-phases').innerHTML=TrafficEngine.stages.map((s,i)=>`<div class="junction-phase ${i===e.stage?'current':''}" data-stage="${i}"><span class="phase-name">${window.junctionStageName(i,state.lang)}</span><small class="phase-state">${i===e.stage?(e.phase==='green'?l.signalGreen:e.phase==='amber'?l.signalAmber:l.signalClear):state.lang==='ar'?'غير نشطة':'Inactive'}</small></div>`).join('');}
  window.decisionUI?.paint(e,engines.baseline,engines.optimized);
  paintEco();
 }
 function sync(){if(lang!==state.lang)buildEco();paint();}
 function reset(){seekGeneration++;seeking=false;$('#map').setAttribute('aria-busy','false');init();state.started=false;state.running=false;state.complete=false;state.motionPaused=true;paint();}
 function advance(dt){engines.baseline.step(dt);engines.optimized.step(dt);if(engines.baseline.collisions().length||engines.optimized.collisions().length){fail=true;state.running=false;}}
 async function seek(seconds){
  const generation=++seekGeneration;seeking=true;state.running=false;state.motionPaused=true;init();
  $('#map').setAttribute('aria-busy','true');
  const count=Math.round(seconds*20);
  for(let i=0;i<count;i++){
   if(generation!==seekGeneration)return false;
   advance(.05);
   if(i%100===99){paint();$('#run-status').textContent=state.lang==='ar'?'جارٍ إعادة حساب التجربة…':'Rebuilding experiment…';await new Promise(requestAnimationFrame);}
  }
  if(generation!==seekGeneration)return false;
  seeking=false;$('#map').setAttribute('aria-busy','false');state.complete=seconds>=DURATION;state.started=seconds>0;updateStage();paint();return true;
 }

 function toggle(){if(fail||seeking)return;if(state.complete)reset();state.running=!state.running;state.motionPaused=!state.running;if(state.running)state.started=true;updateStage();}
 function frame(now){const dt=last?Math.min(.1,(now-last)/1000):0;last=now;if(state.running&&!document.hidden){accumulator+=dt*speed;while(accumulator>=.05&&state.running){advance(.05);accumulator-=.05;if(time()>=DURATION-.001){state.running=false;state.complete=true;updateStage();}}paintElapsed+=dt;if(paintElapsed>=1/24){paint();paintElapsed=0;}}requestAnimationFrame(frame);}
 window.trafficUI={mount,paint,sync,reset,toggle,seek};init();buildEco();mount();$('#motion').onclick=toggle;requestAnimationFrame(frame);if(location.hash==='#ecotwin')route();
})();
